@log_input_and_output
def verify_statuses_of_cells(connection, cells_ids, cells_type, status_variant):
    """
    Verifies statuses of cells with IDs provided in cells_ids
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cells_ids: IDs of cells for which statuses will be verified, e.g. [1, 3]
    :type cells_ids: list of int or str
    :param cells_type: type of cells, can be nr, lte, wcdma or gsm
    :type cells_type: str
    :param status_variant: variant of statuses expected for cells, can be online, dependency, failed, blocked or locked
    :type status_variant: str
    :raises IncorrectStatus: when cell actual statuses do not match expected statuses
    :raises CellInfoNotFound: when provided cell ID is not found among all cell dist names present on BTS
    """
    cells_ids = convert_to_list(cells_ids)
    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection)
    cell_distnames = disable_logging(admin_info_model.get_cell_distnames_from_configured_rats, connection=connection)[cells_type]
    log_result(f"All Cell dist names for cells type '{cells_type}': {cell_distnames}")

    for cell_id in cells_ids:
        confi_cell_distn = next((distn for distn in cell_distnames if distn.split("-")[-1] == str(cell_id)), None)
        if not confi_cell_distn:
            raise CellInfoNotFound(f"Could not match cell ID: {cell_id} with any configured cell dist names present on BTS, "
                                   f"all dist names: {cell_distnames}")
        expected_statuses = CellFactory.create_cell(cells_type, status_variant, connection, cell_id).get_expected_statuses()
        log_iteration(f"Verifying statuses for {cells_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, all_cell_statuses[confi_cell_distn])


@log_input_and_output
def verify_cell_statuses(connection, status_variant, cells_distnames=None):
    """
    Verifies statuses of all cells if arg: `cells_distnames` not provided, otherwise verifies statuses of provided cells.

    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param status_variant: variant of statuses expected for cells, all available variants can be found in,
                           path: 'procedures.resources.python.status_check.cells.cell_factory.CellFactory'
    :type status_variant: str
    :param cells_distnames: configuration cell dist name or list of dist names to verify statuses,
                            defaults to None, which means all cells will be verified,
                            e.g. 'MRBTS-50521/NRBTS-50521/NRCELL-1' or ['MRBTS-50521/NRBTS-50521/NRCELL-1', 'MRBTS-50521/LNBTS-50521/LNCEL-1']
    :type cells_distnames: None | str | list[str]
    :raises CellInfoNotFound: when provided cell dist name is not found among all cell dist names present on BTS
    """
    cell_distns = convert_to_list(cells_distnames) if cells_distnames else []
    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection)
    cell_distns = cell_distns or all_cell_statuses.keys()

    for cell_distn in cell_distns:
        cell_id, cell_type = admin_info_model.get_cell_id_type_from_distname(cell_distn)
        actual_statuses = all_cell_statuses.get(cell_distn, None)
        if not actual_statuses:
            raise CellInfoNotFound(f"Could not found cell configuration dist name: {cell_distn} among all cell dist names present on BTS.")

        expected_statuses = CellFactory.create_cell(cell_type, status_variant, connection, cell_id).get_expected_statuses()
        log_iteration(f"Verifying statuses for {cell_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, actual_statuses)


@log_input_and_output
def verify_specific_variants_for_specific_cells(connection, cell_ids_types_variants):
    """
    Verifies statuses for various cell types with specified status variant.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_ids_types_variants: list of tuples [(val1=configured_cell_id, val2=cell_type, val3=status_variant)]
     i.e. [(1, 'nr', 'online'), (2, 'lte', 'failed')], status_variant can be: active, online, offline, failed,
     dependency, blocked, locked, degraded, dedicated_for_rat_reset.
    :type cell_ids_types_variants: list of tuples(Union[int, str], str, str)
    :raises IncorrectStatus: when cell actual statuses do not match expected statuses
    """
    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection)

    for cell in cell_ids_types_variants:
        cell_id, cell_type, status_variant = cell
        cell_distns = admin_info_model.match_cell_dist_names_with_config_id(connection=connection, cell_type=cell_type, cell_config_id=cell_id)
        confi_cell_distn = cell_distns['configuration']
        expected_statuses = CellFactory.create_cell(cell_type, status_variant, connection, cell_id).get_expected_statuses()
        log_iteration(f"Verifying statuses for {cell_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, all_cell_statuses[confi_cell_distn])


@log_input_and_output
def verify_various_variants_for_various_cells(connection, cells_distnames_variants):
    """
    Verifies statuses for various cell(s) types (NR, LTE) with specified status variant per cell, based on cell configuration dist names.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cells_distnames_variants: list of tuples [(configured_cell_distn, status_variant), ...]
                                     e.g. [('MRBTS-50521/NRBTS-50521/NRCELL-1', 'online'), ('MRBTS-50521/LNBTS-50521/LNCEL-1','failed')],
                                     all available variants can be found in,
                                     path: 'procedures.resources.python.status_check.cells.cell_factory.CellFactory'
    :type cells_distnames_variants: List[Tuple[str, str]]
    :raises IncorrectStatus: when cell actual statuses do not match expected statuses
    """
    cell_distnames = [distn for distn, _ in cells_distnames_variants]
    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection, cell_distns=cell_distnames)

    for cell_distn, status_variant in cells_distnames_variants:
        cell_id, cell_type = admin_info_model.get_cell_id_type_from_distname(cell_distn)
        expected_statuses = CellFactory.create_cell(cell_type, status_variant, connection, cell_id).get_expected_statuses()
        log_iteration(f"Verifying statuses for {cell_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, all_cell_statuses[cell_distn])


@log_input_and_output
def verify_specific_statuses_for_specific_cells(connection, cells_ids, cells_type, operational_state=None, administrative_state=None,
                                                availability_status=None, usage_state=None, blocking_state=None, procedural_status=None,
                                                barring_status=None, energy_saving_state=None):
    """
    Verifies statuses of cells with IDs provided in cells_ids for specified statuses only. All provided cells must be
    of the same type. User can choose which statuses should be verified by providing them as arguments.
    If no statuses are provided, an exception is raised.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cells_ids: IDs of cells for which statuses will be verified, e.g. [1, 3]
    :type cells_ids: list of int or str
    :param cells_type: type of cells, can be nr, lte, wcdma or gsm
    :type cells_type: str
    :param operational_state: operationalState status expected for cells
    :type operational_state: str
    :param administrative_state: administrativeState status expected for cells
    :type administrative_state: str
    :param availability_status: availabilityStatus status expected for cells
    :type availability_status: str
    :param usage_state: usageState status expected for cells
    :type usage_state: str
    :param blocking_state: blockingState status expected for cells
    :type blocking_state: str
    :param procedural_status: proceduralStatus status expected for cells
    :type procedural_status: str
    :param barring_status: barringStatus status expected for cells
    :type barring_status: str
    :param energy_saving_state: energySavingState status expected for cells
    :type energy_saving_state: str
    :raises MissingExpectedStatuses: when no statuses are provided for verification
    :raises IncorrectStatus: when cell actual statuses do not match expected statuses
    """
    cells_ids = convert_to_list(cells_ids)
    expected_statuses = {
        "operationalState": operational_state,
        "administrativeState": administrative_state,
        "availabilityStatus": availability_status,
        "usageState": usage_state,
        "blockingState": blocking_state,
        "proceduralStatus": procedural_status,
        "barringStatus": barring_status,
        "energySavingState": energy_saving_state
    }
    expected_statuses = {keys: values for keys, values in expected_statuses.items() if values is not None}
    if not expected_statuses:
        raise MissingExpectedStatuses("No cells statuses provided for verification")

    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection)
    cell_distnames = disable_logging(admin_info_model.get_cell_distnames_from_configured_rats, connection=connection)[cells_type]
    log_result(f"All Cell dist names for cells type '{cells_type}': {cell_distnames}")

    for cell_id in cells_ids:
        confi_cell_distn = next((distn for distn in cell_distnames if distn.split("-")[-1] == str(cell_id)), None)
        if not confi_cell_distn:
            raise CellInfoNotFound(f"Could not match cell ID: {cell_id} with any configured cell dist names present on BTS, "
                                   f"all dist names: {cell_distnames}")
        log_iteration(f"Verifying statuses for {cells_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, all_cell_statuses[confi_cell_distn])


@log_input_and_output
def verify_statuses_of_all_cells(connection, cells_type, status_variant, skip_lte_iot_hosted_cells=True):
    """
    Verifies statuses of all cells with given type
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cells_type: type of cells, can be nr, lte, wcdma or gsm
    :type cells_type: str
    :param status_variant: variant of statuses expected for cells, can be online, dependency, failed, blocked or locked
    :type status_variant: str
    :param skip_lte_iot_hosted_cells: True if verification of LTE IoT guardband and inband cells statuses should be
                                      skipped, False otherwise. Defaults to True
    :type skip_lte_iot_hosted_cells: bool
    :raises IncorrectStatus: when cell actual statuses do not match expected statuses
    """
    all_cell_statuses = admin_info_model.get_cell_statuses(connection=connection)
    cell_distnames = disable_logging(admin_info_model.get_cell_distnames_from_configured_rats, connection=connection)[cells_type]
    log_result(f"All Cell dist names for cells type '{cells_type}': {cell_distnames}")

    if cells_type == "lte" and skip_lte_iot_hosted_cells:
        iot_hosted_cells = _get_cell_ids_of_lte_iot_hosted_cells(connection)
        if iot_hosted_cells:
            for cell_distn in iot_hosted_cells:
                cell_distnames.remove(cell_distn)
            log_warning(f"Status verification of LTE IoT cells with following IDs will be skipped: {iot_hosted_cells}")

    for cell_distn in cell_distnames:
        cell_id, _ = admin_info_model.get_cell_id_type_from_distname(cell_distn)
        expected_statuses = CellFactory.create_cell(cells_type, status_variant, connection, cell_id).get_expected_statuses()
        log_iteration(f"Verifying statuses for {cells_type.upper()} cell: {cell_id}")
        _verify_expected_statuses(expected_statuses, all_cell_statuses[cell_distn])


@log_input_and_output
def get_cell_ids_types_variants_for_shared_rmod_setups(connection, standalone_cell_status_variant='online',
                                                       shared_rmod_cell_status_variant='online'):
    """
    Returns cell IDs, cell types and statuses variants with the distinction to shared rmod setups.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param standalone_cell_status_variant: expected status variant for standalone rmods' cells, e.g. 'blocked',
           default to 'online'
    :type standalone_cell_status_variant: str
    :param shared_rmod_cell_status_variant: expected status variant for shared rmods' cells, e.g. 'blocked',
           default to 'online'
    :return: list of tuples with cell ID, cell type and status variant
    :rtype: list of tuples (int, str, str)
    """
    cell_ids_types_variants = []

    rats = admin_info_model.get_rats(connection=connection)
    shared_rmods_indexes = admin_info_model.get_shared_rmods_indexes(connection=connection)

    for rat in rats:
        cell_ids = admin_info_model.get_cell_ids_from_specific_rat(connection=connection, cell_type=rat)
        cell_ids_for_shared_rmods = admin_info_model.get_cells_ids_for_specific_rus(connection=connection,
                                                                                    rmod_ids=shared_rmods_indexes,
                                                                                    cell_type=rat)
        for cell_id in cell_ids:
            if admin_info_model.is_iot_cell(connection=connection, cell_type=rat, cell_id=cell_id) and rat == 'lte':
                continue
            variant = shared_rmod_cell_status_variant if cell_id in cell_ids_for_shared_rmods \
                else standalone_cell_status_variant
            cell_ids_types_variants.append((cell_id, rat, variant))
    return cell_ids_types_variants


@log_input_and_output
def verify_statuses_of_all_rmods(connection, status_variant='online'):
    """
    Verifies statuses of all rmods
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param status_variant: variant of statuses expected for rmods, can be online, disabled or locked
    :type status_variant: str
    :raises IncorrectStatus: when rmod actual statuses do not match expected statuses
    """
    statuses = admin_info_model.get_statuses_of_all_rmods(connection)
    rmods_link_protocols = admin_info_model.get_rmods_protocols(connection)
    rmods_ran_protocols = admin_info_model.get_rmods_ran_protocols(connection)

    for rmod_id, rmod_statuses in statuses.items():
        expected_statuses = RmodFactory.create_rmod(
            rmod_ran_protocol=rmods_ran_protocols[rmod_id],
            rmod_link_protocol=rmods_link_protocols[rmod_id]
        ).get_expected_statuses(status_variant)
        log_iteration("Verifying statuses for RMOD {}".format(rmod_id))
        _verify_expected_statuses(expected_statuses, rmod_statuses)


@log_input_and_output
def verify_statuses_of_all_rmods_with_separate_status_for_shared_rmod(connection,
                                                                      standalone_rmod_status_variant='online',
                                                                      shared_rmod_status_variant='online'):
    """
    Verifies current statuses for given variants separately for not shared rmods and shared rmods.
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param standalone_rmod_status_variant: variant of statuses expected for standalone rmods, e.g. 'locked',
           default to 'online'
    :type standalone_rmod_status_variant: str
    :param shared_rmod_status_variant: variant of statuses expected for shared rmods, e.g.'disabled'
           default to 'online'
    :type shared_rmod_status_variant: str
    :raises IncorrectStatus: when rmod actual statuses do not match expected statuses
    """
    statuses = admin_info_model.get_statuses_of_all_rmods(connection=connection)
    shared_rmods_indexes = admin_info_model.get_shared_rmods_indexes(connection=connection)
    rmods_link_protocols = admin_info_model.get_rmods_protocols(connection=connection)
    rmods_ran_protocols = admin_info_model.get_rmods_ran_protocols(connection)

    for rmod_id, rmod_statuses in statuses.items():
        status_variant = shared_rmod_status_variant if int(rmod_id) in shared_rmods_indexes \
            else standalone_rmod_status_variant
        expected_statuses = RmodFactory.create_rmod(
            rmod_ran_protocol=rmods_ran_protocols[rmod_id],
            rmod_link_protocol=rmods_link_protocols[rmod_id]
        ).get_expected_statuses(status_variant)
        log_iteration("Verifying statuses for RMOD {}".format(rmod_id))
        _verify_expected_statuses(expected_statuses, rmod_statuses)


@log_input_and_output
def verify_statuses_of_all_uncommissioned_rmods(connection, nr_of_rmods):
    """
    Verifies statuses of all uncommissioned rmods
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param nr_of_rmods: number of expected detected uncommissioned rmods.
     Rmods may not be all detected after config reset, that's why function waits for given number
    :type nr_of_rmods: int
    :raises IncorrectStatus: when rmod actual statuses do not match expected statuses
    :raises HwNotReachable: when given number of rmods is not yet detected
    """
    statuses = admin_info_model.get_statuses_of_all_rmods(connection, dist_name_type="internal")
    if len(statuses) < nr_of_rmods:
        raise HwNotReachable(
            f"Not all radios detected. Expected nr of RMODS {nr_of_rmods}, got {len(statuses)}")

    rmods_link_protocols = admin_info_model.get_rmods_protocols(connection, dist_name_type="internal")
    rmods_ran_protocols = admin_info_model.get_rmods_ran_protocols(connection, dist_name_type="internal")
    for rmod_id, rmod_statuses in statuses.items():
        expected_statuses = RmodFactory.create_rmod(
            rmod_ran_protocol=rmods_ran_protocols[rmod_id],
            rmod_link_protocol=rmods_link_protocols[rmod_id]
        ).get_expected_statuses("uncommissioned")
        log_iteration("Verifying statuses for RMOD {}".format(rmod_id))
        _verify_expected_statuses(expected_statuses, rmod_statuses)


@log_input_and_output
def verify_specified_count_of_rmods_are_initializing(connection, nr_of_rmods):
    """
    Verifies if all uncommissioned rmods are initializing
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param nr_of_rmods: number of expected detected uncommissioned rmods.
     Rmods may not be all detected after config reset, that's why function waits for given number
    :type nr_of_rmods: int
    :raises IncorrectStatus: when rmod actual statuses do not match expected statuses
    :raises HwNotReachable: when given number of rmods is not yet detected
    """
    statuses = admin_info_model.get_statuses_of_all_rmods(connection, dist_name_type="internal")
    if len(statuses) < nr_of_rmods:
        raise HwNotReachable(
            f"Not all radios detected. Expected nr of RMODS {nr_of_rmods}, got {len(statuses)}")

    for rmod_id, rmod_statuses in statuses.items():
        log_iteration("Verifying procedural status for RMOD {}".format(rmod_id))
        rmod_status = rmod_statuses.get('proceduralStatus', None)
        if rmod_status == 'not initialized':
            raise IncorrectStatus("Incorrect status detected! RMOD {} is in status 'not initialized'!".format(rmod_id))


