@log_input_and_output
def verify_statuses_of_rmods(connection, status_variant, rmod_ids):
    """
    Verifies statuses of RMODs with given ids
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param status_variant: variant of statuses expected for rmods, can be active, online, offline, disabled or locked
    :type status_variant: str
    :param rmod_ids: IDs of RMODs, e.g. ['2', '3']
    :type rmod_ids: Union[int, str, List[Union[int, str]]]
    :raises IncorrectStatus: when rmod actual statuses do not match expected statuses
    """
    statuses = admin_info_model.get_statuses_of_all_rmods(connection)
    rmods_link_protocols = admin_info_model.get_rmods_protocols(connection)
    rmods_ran_protocols = admin_info_model.get_rmods_ran_protocols(connection)

    for rmod_id in rmod_ids:
        expected_statuses = RmodFactory.create_rmod(
            rmod_ran_protocol=rmods_ran_protocols[str(rmod_id)],
            rmod_link_protocol=rmods_link_protocols[str(rmod_id)]
        ).get_expected_statuses(status_variant)
        log_iteration(f"Verifying statuses for RMOD {rmod_id}\n"
                      f"Expected statuses: {expected_statuses}\nActual statuses: {statuses[str(rmod_id)]}")
