@log_input_and_output
def verify_specific_statuses_for_specific_rmods(connection, rmod_ids, operational_state=None,
                                                administrative_state=None, availability_status=None,
                                                usage_state=None, blocking_state=None, procedural_status=None):
    """
    Verifies operational state of rmods with given ids
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param operational_state: expected operational state for rmods, can be enabled or disabled
    :type operational_state: str
    :param rmod_ids: IDs of RMODs, e.g. '1' or ['2', '3']
    :type rmod_ids: Union[int, str, List[Union[int, str]]]
    :param operational_state: operationalState status expected for rmods
    :type operational_state: str
    :param administrative_state: administrativeState status expected for rmods
    :type administrative_state: str
    :param availability_status: availabilityStatus status expected for rmods
    :type availability_status: str
    :param usage_state: usageState status expected for rmods
    :type usage_state: str
    :param blocking_state: blockingState status expected for rmods
    :type blocking_state: str
    :param procedural_status: proceduralStatus status expected for rmods
    :type procedural_status: str
    :raises MissingExpectedStatuses: when no statuses are provided for verification
    :raises IncorrectStatus: when rmod actual operational state do not match expected status
    """
    if not isinstance(rmod_ids, list):
        rmod_ids = [rmod_ids]

    expected_statuses = {
        "operationalState": operational_state,
        "administrativeState": administrative_state,
        "availabilityStatus": availability_status,
        "usageState": usage_state,
        "blockingState": blocking_state,
        "proceduralStatus": procedural_status,
    }
    expected_statuses = {keys: values for keys, values in expected_statuses.items() if values is not None}

    statuses = admin_info_model.get_statuses_of_all_rmods(connection)
    for rmod_id in rmod_ids:
        log_iteration("Verifying statuses for RMOD {}".format(rmod_id))
        _verify_expected_statuses(expected_statuses, statuses[str(rmod_id)])


