@log_input_and_output
def verify_selected_statuses_of_bts(connection, bts_statuses_to_check, bts_status_variant):
    """
    Verifies statuses of BTS
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param bts_statuses_to_check: list of statuses to check, e.g.:
                                  ['blockingState', 'operationalState', 'proceduralState']
    :type bts_statuses_to_check: list of str
    :param bts_status_variant: variant of statuses expected for BTS; available variants: OnAir, Test, Configured,
                               Blocked, NotComissioned, IntegratedToRan;
    :type bts_status_variant: str
    :raises IncorrectStatus: when BTS actual statuses do not match expected statuses
    """
    bts_statuses = admin_info_model.get_bts_statuses(connection)
    expected_statuses = Bts.get_expected_statuses(bts_status_variant)
    selected_statuses = {status_name: status_value for status_name, status_value in expected_statuses.items()
                         if status_name in bts_statuses_to_check}

    if not selected_statuses:
        log_warning(f"Given statuses to check ({bts_statuses_to_check}) are not present in expected statuses "
                    f"({expected_statuses}) for BTS.")
    else:
        missing_statuses = [status for status in bts_statuses_to_check if status not in expected_statuses]
        if missing_statuses:
            log_warning(f"Some statuses to check ({missing_statuses}) are not present in expected statuses "
                        f"({expected_statuses}) for BTS.")
        _verify_expected_statuses(selected_statuses, bts_statuses)


@log_input_and_output
def verify_procedural_state_of_bts(connection, procedural_state="OnAir"):
    """
    Verify BTS Procedural State
    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :param procedural_state: BTS procedural States, Configured/OnAir/Commissioned/IntegratedToRan/Test/Blocked
    :type procedural_state: str
    :return: None
    """
    detected_procedural_state = admin_info_model.get_bts_procedural_state(connection=connection)
    if detected_procedural_state != procedural_state:
        raise IncorrectStatus(
            "Incorrect status detected! Expected status: {}, actual status: {}".format(
                procedural_state, detected_procedural_state))


