@log_input_and_output
def verify_statuses_of_rats(connection, rats=None, status_variant='enabled'):
    """
    Verifies statuses of provided RAT(s)
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rats: RATs to verify e.g. 'nr' or ['nr', 'lte'] or [('nr', 'disabled'), ('lte', 'enabled')].
                 In case of tuples, the first arg is RAT and the second is status_variant.
                 If None, all RATs will be verified with default status_variant.
    :type rats: Union[str, list[Union[str, tuple[str, str]]]]
    :param status_variant: variant of statuses expected for RAT, can be 'enabled', 'disabled', 'offline', 'degraded',
                           'not_commissioned' or 'dedicated_for_rat_reset'.
    :type status_variant: str
    :raises IncorrectStatus: when RAT actual statuses do not match expected statuses
    """

    if rats is None:
        rats = admin_info_model.get_rats(connection)

    if isinstance(rats, str):
        rats = [(rats, status_variant)]
    elif isinstance(rats, list) and rats and isinstance(rats[0], str):
        rats = [(rat, status_variant) for rat in rats]

    for rat in rats:
        rat_type, status_variant = rat[0], rat[1]
        statuses = admin_info_model.get_rat_statuses(connection=connection, rat=rat_type)
        expected_statuses = Rat.get_expected_statuses(status_variant)
        log_iteration(f"Verifying statuses for RAT {rat_type}\n"
                      f"Expected statuses: {expected_statuses}\nActual statuses: {statuses}")
        _verify_expected_statuses(expected_statuses, statuses)


@log_input_and_output
def is_rmod_locked(connection, rmod_id):
    """
    Checks whether rmod with given id is locked
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param rmod_id: ID of RMOD, e.g. 2
    :type rmod_id: Union[int, str]
    :return: True if rmod is locked, false otherwise
    :rtype: bool
    """
    statuses = admin_info_model.get_statuses_of_specific_rmod(connection, rmod_id)
    return statuses['administrativeState'] == 'Locked'


@log_input_and_output
def is_cell_blocked(connection, cell_id, cell_type):
    """
    Checks whether cell with given id is blocked
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :param cell_id: ID of cell, e.g. 2
    :type cell_id: Union[int, str]
    :param cell_type: ID of RMOD, e.g. 2
    :type cell_type: Union[int, str]
    :return: True if rmod is locked, false otherwise
    :rtype: bool
    """
    statuses = admin_info_model.get_statuses_of_specific_cell(cell_id=cell_id, cell_type=cell_type,
                                                              connection=connection)
    return statuses['blockingState'] == 'Blocked'


def verify_if_any_cell_down(connection):
    """
    Checks if any cell is down
    :param connection: AdminConnection object or, if used, string name alias.
    :type connection: AdminConnection or str
    :raises IncorrectStatus: when all cell are online
    """
    cells_ids_with_type = admin_info_model.get_cell_ids_from_configured_rats(connection)
    cell_statuses = {}
    for cell_type in cells_ids_with_type.keys():
        statuses = admin_info_model.get_statuses_of_all_cells(cell_type, connection)
        cell_statuses.update({f"{cell_id}_{cell_type}": statuses for cell_id, statuses in statuses.items()})

    for cell, cell_statuses in cell_statuses.items():
        if cell_statuses['operationalState'] == 'disabled':
            return

    raise IncorrectStatus("Cells are still online!")


@log_input_and_output
def prepare_cell_statuses(cell_distns, status_variant):
    """
    Prepares cells with statuses for method `verify_specific_variants_for_specific_cells`

    :param cell_distns: list of configuration cell dist names, e.g. ['MRBTS-40612/NRBTS-50612/NRCELL-3', 'MRBTS-40612/LNBTS-40612/LNCEL-2']
    :type cell_distns: list[str]
    :param status_variant: can be: active, online, offline, failed, blocked, locked, dependency, energy_saving, ...
    :type status_variant: str
    :return: List of tuples with (configured cell id, cell type, status variant) e.g [('1', 'lte', 'online'), ('2', 'nr', 'online')]
    :rtype: list[tuples]
    """

    cells_with_statuses = []
    for cell_distn in cell_distns:
        cell_id, cell_type = admin_info_model.get_cell_id_type_from_distname(cell_distn)
        cells_with_statuses.append((cell_id, cell_type, status_variant))

    return cells_with_statuses


def _get_statuses_by_serial(statuses, serial_number):
    for unit in statuses:
        if unit["serialNumber"] == serial_number:
            return {'operationalState': unit['status']['operationalState'],
                    'availabilityStatus': unit['status'].get('availabilityStatus'),
                    'usageState': unit['status']['usageState'],
                    'administrativeState': unit['status']['administrativeState'],
                    'proceduralStatus': unit['status']['proceduralStatus']}

    raise HwNotReachable("Unit with provided serial number: {} does not exist in current configuration"
                         .format(serial_number))


def _verify_expected_statuses(expected_statuses, actual_statuses):
    log_step(f"Verifying statuses ...\n"
             f"Expected: {dict(sorted(expected_statuses.items()))}\n"
             f"Actual:   {dict(sorted(actual_statuses.items()))}")
    for status_name, status_value in expected_statuses.items():
        if status_value != actual_statuses.get(status_name, None):
            raise IncorrectStatus(
                "Incorrect {} detected! Expected status: {}, actual status: {}".format(
                    status_name, status_value, actual_statuses[status_name]))


def _verify_expected_procedural_state(expected_statuses, actual_statuses):
    if expected_statuses['proceduralStatus'] != actual_statuses.get('proceduralStatus', None):
        raise IncorrectStatus(
            "Incorrect procedural status detected! Expected status: {}, actual status: {}".format(
                expected_statuses['proceduralStatus'], actual_statuses.get('proceduralStatus', None)))


@log_input_and_output
@raise_when_output_is_empty
def _get_statuses_of_all_smods(connection, timeout=60):
    """
    Get all statuses of all SMODs

    :param connection: AdminConnection object or, if used, string name alias
    :type connection: AdminConnection or str
    :param timeout: timeout for positive procedure result
    :return: dictionary with SMOD's distName as key and SMOD's statuses as value
    """
    adm = admin()
    smods_status = {}
    system_module_info = adm.get_bts_info(connection=connection, timeout=timeout)['systemModules']
    for smod in system_module_info:
        smod_distname = smod['id']['runtime']
        smod_status = smod['status']
        smods_status[smod_distname] = smod_status
    return smods_status


@log_input_and_output
def _get_cell_ids_of_lte_iot_hosted_cells(connection):
    """
    Gets list of cell configuration dist names for all LTE iot hosted (guardband and inband) cells.

    :param connection: AdminConnection object or if used, string name alias.
    :type connection: AdminConnection or str
    :return: list of configuration dist names for LTE iot hosted (guardband and inband) cells,
             example: ['MRBTS-40615/LNBTS-40615/LNCEL-24', 'MRBTS-40615/LNBTS-40615/LNCEL-26']
    :rtype: list(str)
    """
    adm = admin()
    cells_info = adm.get_cells_info(connection=connection, cell_type="lte")

    lte_iot_hosted_cells = []
    for cell in cells_info:
        if cell['technology'] == 'NB-IoT-FDD':
            if cell['narrowbandIotMode'] == "inband" or cell['narrowbandIotMode'] == "guardband":
                lte_iot_hosted_cells.append(cell['id']['configuration'])

    return lte_iot_hosted_cells
